#!/usr/bin/env python3
"""Replace CloudShare's tabbed configuration form with a true sequential setup assistant."""
from __future__ import annotations
import sys
from pathlib import Path

PROVISIONER_SOURCE = 'package com.ksp.cryptobot.cloudshare\n\nimport android.content.Context\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.withContext\nimport okhttp3.MediaType.Companion.toMediaType\nimport okhttp3.MultipartBody\nimport okhttp3.OkHttpClient\nimport okhttp3.Request\nimport okhttp3.RequestBody.Companion.toRequestBody\nimport org.json.JSONArray\nimport org.json.JSONObject\nimport java.net.URLEncoder\nimport java.security.SecureRandom\nimport java.util.Base64\nimport java.util.UUID\nimport java.util.concurrent.TimeUnit\n\ndata class CloudShareProvisioningStep(\n    val name: String,\n    val status: String,\n    val detail: String\n)\n\ndata class CloudShareProvisioningResult(\n    val success: Boolean,\n    val workerUrl: String = "",\n    val d1DatabaseId: String = "",\n    val r2BucketName: String = "",\n    val workerName: String = "",\n    val firstInviteCode: String = "",\n    val steps: List<CloudShareProvisioningStep> = emptyList(),\n    val error: String = ""\n)\n\nclass CloudShareProvisioner(context: Context) {\n    private val appContext = context.applicationContext\n    private val store = CloudShareSettingsStore(appContext)\n    private val engine = CloudShareSyncEngine(appContext)\n    private val http = OkHttpClient.Builder()\n        .connectTimeout(30, TimeUnit.SECONDS)\n        .readTimeout(45, TimeUnit.SECONDS)\n        .writeTimeout(45, TimeUnit.SECONDS)\n        .build()\n\n    suspend fun provision(\n        accountId: String,\n        apiToken: String,\n        workerName: String,\n        d1Name: String,\n        r2BucketName: String,\n        euResidency: Boolean = true,\n        backfillEnabled: Boolean = true,\n        syncIntervalMinutes: Int = 5,\n        onProgress: (CloudShareProvisioningStep) -> Unit = {}\n    ): CloudShareProvisioningResult = withContext(Dispatchers.IO) {\n        val steps = mutableListOf<CloudShareProvisioningStep>()\n        fun progress(name: String, status: String, detail: String) {\n            val row = CloudShareProvisioningStep(name, status, detail)\n            steps += row\n            onProgress(row)\n        }\n\n        val cleanAccount = accountId.trim()\n        val cleanToken = apiToken.trim()\n        val cleanWorker = safeResourceName(workerName, "cts-cloudshare")\n        val cleanD1 = safeResourceName(d1Name, "cts-cloudshare-db")\n        val cleanR2 = safeResourceName(r2BucketName, "cts-cloudshare-backups")\n\n        require(cleanAccount.matches(Regex("^[a-fA-F0-9]{32}$"))) {\n            "Cloudflare Account ID does not look valid."\n        }\n        require(cleanToken.length >= 20) {\n            "Cloudflare API token is missing or too short."\n        }\n\n        val adminToken = randomSecret()\n        val firstInvite = randomSecret()\n\n        try {\n            progress("Cloudflare authorization", "RUNNING", "Checking the scoped API token.")\n            api(cleanToken, "GET", "/accounts/$cleanAccount/d1/database?per_page=1")\n            progress("Cloudflare authorization", "PASS", "Token can access D1 for this account.")\n\n            progress("D1 database", "RUNNING", "Finding or creating $cleanD1.")\n            val databaseId = ensureD1(cleanAccount, cleanToken, cleanD1, euResidency)\n            progress("D1 database", "PASS", "D1 ready: $cleanD1.")\n\n            progress("D1 schema", "RUNNING", "Creating CloudShare tables and the first invitation.")\n            initializeSchema(cleanAccount, cleanToken, databaseId, firstInvite)\n            progress("D1 schema", "PASS", "Schema and initial invitation ready.")\n\n            progress("R2 storage", "RUNNING", "Finding or creating $cleanR2.")\n            ensureR2(cleanAccount, cleanToken, cleanR2, euResidency)\n            progress("R2 storage", "PASS", "R2 bucket ready: $cleanR2.")\n\n            progress("Worker deployment", "RUNNING", "Deploying CloudShare Worker and D1/R2 bindings.")\n            deployWorker(cleanAccount, cleanToken, cleanWorker, databaseId, cleanR2, adminToken)\n            progress("Worker deployment", "PASS", "Worker uploaded with DB/BACKUPS bindings.")\n\n            progress("Workers.dev route", "RUNNING", "Enabling Worker HTTPS endpoint.")\n            enableWorkerSubdomain(cleanAccount, cleanToken, cleanWorker)\n            val subdomain = ensureAccountSubdomain(cleanAccount, cleanToken)\n            val workerUrl = "https://$cleanWorker.$subdomain.workers.dev"\n            progress("Workers.dev route", "PASS", workerUrl)\n\n            progress("Worker health", "RUNNING", "Testing /v1/health before saving CloudShare credentials.")\n            val health = CloudShareClient(workerUrl).health()\n            require(health["ok"]?.toString()?.equals("true", true) == true) {\n                "CloudShare health endpoint did not report ok=true."\n            }\n            progress("Worker health", "PASS", "Worker/D1/R2 health check passed.")\n\n            progress("Owner setup", "RUNNING", "Saving CloudShare owner token in encrypted Android storage.")\n            store.apiUrl = workerUrl\n            store.saveAdminToken(adminToken)\n            progress("Owner setup", "PASS", "Owner token stored encrypted. Cloudflare token was not stored.")\n\n            progress("Register this device", "RUNNING", "Registering this phone with the generated invitation.")\n            val credentials = engine.register(firstInvite)\n            progress("Register this device", "PASS", "Registered client ${credentials.clientId.take(12)}…")\n\n            progress("Client verification", "RUNNING", "Checking client and intelligence endpoints.")\n            val authenticated = CloudShareClient(workerUrl, credentials = credentials)\n            authenticated.clientStatus()\n            authenticated.intelligenceStatus()\n            progress("Client verification", "PASS", "Client authentication and intelligence API passed.")\n\n            progress("Initial sync", "RUNNING", "Uploading the first local evidence batch and downloading collective intelligence.")\n            store.backfillEnabled = backfillEnabled\n            store.syncIntervalMinutes = syncIntervalMinutes.coerceIn(1, 1440)\n            store.enabled = true\n            val initialSync = engine.syncIfDue(force = true)\n            require(initialSync.error.isBlank()) { "Initial CloudShare sync failed: ${initialSync.error}" }\n            progress(\n                "Initial sync",\n                "PASS",\n                "uploaded=${initialSync.uploaded}, duplicates=${initialSync.duplicates}, backfill=${initialSync.backfilled}, downloaded=${initialSync.downloaded}"\n            )\n\n            progress("CloudShare", "PASS", "CloudShare enabled. Local trading remains independent.")\n\n            CloudShareProvisioningResult(\n                success = true,\n                workerUrl = workerUrl,\n                d1DatabaseId = databaseId,\n                r2BucketName = cleanR2,\n                workerName = cleanWorker,\n                firstInviteCode = firstInvite,\n                steps = steps\n            )\n        } catch (error: Exception) {\n            progress("Provisioning", "FAIL", error.message ?: error.javaClass.simpleName)\n            CloudShareProvisioningResult(\n                success = false,\n                steps = steps,\n                error = error.message ?: error.javaClass.simpleName\n            )\n        }\n    }\n\n    /** Verify the one-time user API token before asking for any infrastructure details. */\n    suspend fun verifyProvisioningToken(apiToken: String): CloudShareProvisioningStep = withContext(Dispatchers.IO) {\n        val token = apiToken.trim()\n        require(token.length >= 20) { "Paste the Cloudflare API token first." }\n        val response = api(token, "GET", "/user/tokens/verify")\n        val result = response.optJSONObject("result") ?: JSONObject()\n        val status = result.optString("status")\n        require(status.equals("active", ignoreCase = true)) {\n            "Cloudflare token is not active (status=${status.ifBlank { "unknown" }})."\n        }\n        CloudShareProvisioningStep(\n            "Cloudflare API token",\n            "PASS",\n            "Token is active. It remains only in this setup screen and is never saved by Crypto TradeStation."\n        )\n    }\n\n    /**\n     * Validate the Account ID and each permission CloudShare provisioning needs.\n     * This is deliberately performed before the user presses Create CloudShare so\n     * missing permissions are reported as a guided setup problem, not a deployment error.\n     */\n    suspend fun verifyProvisioningAccess(\n        accountId: String,\n        apiToken: String\n    ): List<CloudShareProvisioningStep> = withContext(Dispatchers.IO) {\n        val account = accountId.trim()\n        val token = apiToken.trim()\n        require(account.matches(Regex("^[a-fA-F0-9]{32}$"))) {\n            "Cloudflare Account ID must be the 32-character ID copied from the Cloudflare dashboard."\n        }\n        require(token.length >= 20) { "Cloudflare API token is missing." }\n\n        val out = mutableListOf<CloudShareProvisioningStep>()\n        suspend fun check(name: String, detail: String, path: String) {\n            try {\n                api(token, "GET", path)\n                out += CloudShareProvisioningStep(name, "PASS", detail)\n            } catch (error: Exception) {\n                out += CloudShareProvisioningStep(\n                    name,\n                    "FAIL",\n                    (error.message ?: error.javaClass.simpleName).take(500)\n                )\n            }\n        }\n\n        check(\n            "D1 Write access",\n            "The token can access D1 for this account.",\n            "/accounts/$account/d1/database?per_page=1"\n        )\n        check(\n            "R2 Storage Write access",\n            "The token can access R2 for this account.",\n            "/accounts/$account/r2/buckets?per_page=1"\n        )\n        check(\n            "Workers Scripts Write access",\n            "The token can access Workers scripts for this account.",\n            "/accounts/$account/workers/scripts"\n        )\n        out\n    }\n\n    suspend fun verifyExisting(workerUrl: String): List<CloudShareProvisioningStep> = withContext(Dispatchers.IO) {\n        val rows = mutableListOf<CloudShareProvisioningStep>()\n        val url = workerUrl.trim().trimEnd(\'/\')\n        try {\n            val health = CloudShareClient(url).health()\n            rows += CloudShareProvisioningStep("Worker health", "PASS", health.toString())\n        } catch (error: Exception) {\n            rows += CloudShareProvisioningStep("Worker health", "FAIL", error.message ?: error.javaClass.simpleName)\n            return@withContext rows\n        }\n\n        val credentials = store.credentials()\n        if (credentials == null) {\n            rows += CloudShareProvisioningStep("Client registration", "WARN", "This device has no CloudShare credentials.")\n            return@withContext rows\n        }\n\n        try {\n            val client = CloudShareClient(url, credentials = credentials)\n            rows += CloudShareProvisioningStep("Client status", "PASS", client.clientStatus().toString())\n            rows += CloudShareProvisioningStep("Intelligence status", "PASS", client.intelligenceStatus().toString())\n        } catch (error: Exception) {\n            rows += CloudShareProvisioningStep("Authenticated API", "FAIL", error.message ?: error.javaClass.simpleName)\n        }\n        rows\n    }\n\n    private suspend fun ensureD1(accountId: String, token: String, name: String, eu: Boolean): String {\n        val encoded = URLEncoder.encode(name, "UTF-8")\n        val list = api(token, "GET", "/accounts/$accountId/d1/database?name=$encoded&per_page=100")\n        val array = list.optJSONArray("result") ?: JSONArray()\n        for (index in 0 until array.length()) {\n            val item = array.optJSONObject(index) ?: continue\n            if (item.optString("name") == name) {\n                return item.optString("uuid").ifBlank { item.optString("id") }\n            }\n        }\n\n        val body = JSONObject().put("name", name)\n        if (eu) body.put("jurisdiction", "eu")\n        val created = api(token, "POST", "/accounts/$accountId/d1/database", body)\n            .getJSONObject("result")\n        return created.optString("uuid").ifBlank { created.getString("id") }\n    }\n\n    private suspend fun initializeSchema(accountId: String, token: String, databaseId: String, inviteCode: String) {\n        val schema = appContext.assets.open("cloudshare_setup/schema.sql").bufferedReader().use { it.readText() }\n        val statements = schema.split(\';\').map { it.trim() }.filter { it.isNotBlank() }\n        for (statement in statements) d1Query(accountId, token, databaseId, statement, emptyList())\n\n        val inviteHash = CloudShareProtocol.sha256(inviteCode)\n        val now = CloudShareProtocol.nowIso()\n        val expires = java.time.Instant.now().plusSeconds(7L * 24L * 3600L).toString()\n        d1Query(\n            accountId, token, databaseId,\n            """INSERT OR REPLACE INTO invites\n               (id, code_hash, label, max_uses, uses, expires_at, revoked, created_at)\n               VALUES (?, ?, ?, 1, 0, ?, 0, ?)""".trimIndent(),\n            listOf(UUID.randomUUID().toString(), inviteHash, "Initial Android setup", expires, now)\n        )\n    }\n\n    private suspend fun d1Query(\n        accountId: String,\n        token: String,\n        databaseId: String,\n        sql: String,\n        params: List<Any?>\n    ): JSONObject {\n        val payload = JSONObject().put("sql", sql).put("params", JSONArray(params))\n        return api(token, "POST", "/accounts/$accountId/d1/database/$databaseId/query", payload)\n    }\n\n    private suspend fun ensureR2(accountId: String, token: String, bucket: String, eu: Boolean) {\n        val encoded = URLEncoder.encode(bucket, "UTF-8")\n        val existing = runCatching { api(token, "GET", "/accounts/$accountId/r2/buckets/$encoded") }.getOrNull()\n        if (existing?.optBoolean("success", false) == true) return\n\n        val headers = if (eu) mapOf("cf-r2-jurisdiction" to "eu") else emptyMap()\n        val body = JSONObject().put("name", bucket).put("storageClass", "Standard")\n        api(token, "POST", "/accounts/$accountId/r2/buckets", body, headers)\n    }\n\n    private suspend fun deployWorker(\n        accountId: String,\n        token: String,\n        workerName: String,\n        databaseId: String,\n        bucket: String,\n        adminToken: String\n    ) {\n        val script = appContext.assets.open("cloudshare_setup/cloudshare-worker.js").bufferedReader().use { it.readText() }\n        val metadata = JSONObject()\n            .put("main_module", "worker.js")\n            .put("compatibility_date", "2026-08-21")\n            .put("bindings", JSONArray()\n                .put(JSONObject().put("type", "d1").put("name", "DB").put("id", databaseId))\n                .put(JSONObject().put("type", "r2_bucket").put("name", "BACKUPS").put("bucket_name", bucket))\n                .put(JSONObject().put("type", "secret_text").put("name", "ADMIN_TOKEN").put("text", adminToken))\n            )\n\n        val multipart = MultipartBody.Builder()\n            .setType(MultipartBody.FORM)\n            .addFormDataPart("metadata", null, metadata.toString().toRequestBody("application/json".toMediaType()))\n            .addFormDataPart(\n                "worker.js", "worker.js",\n                script.toRequestBody("application/javascript+module".toMediaType())\n            )\n            .build()\n\n        val request = Request.Builder()\n            .url("$API_BASE/accounts/$accountId/workers/scripts/$workerName")\n            .header("Authorization", "Bearer $token")\n            .header("Accept", "application/json")\n            .put(multipart)\n            .build()\n        executeCloudflare(request)\n    }\n\n    private suspend fun enableWorkerSubdomain(accountId: String, token: String, workerName: String) {\n        api(\n            token, "POST",\n            "/accounts/$accountId/workers/scripts/$workerName/subdomain",\n            JSONObject().put("enabled", true).put("previews_enabled", false)\n        )\n    }\n\n    private suspend fun ensureAccountSubdomain(accountId: String, token: String): String {\n        val existing = runCatching {\n            api(token, "GET", "/accounts/$accountId/workers/subdomain")\n                .optJSONObject("result")?.optString("subdomain").orEmpty()\n        }.getOrDefault("")\n        if (existing.isNotBlank()) return existing\n\n        val suggested = safeResourceName("cts-${accountId.take(6)}-${randomSecret().take(6)}", "cts-cloudshare").take(40)\n        val created = api(\n            token, "PUT",\n            "/accounts/$accountId/workers/subdomain",\n            JSONObject().put("subdomain", suggested)\n        )\n        return created.getJSONObject("result").getString("subdomain")\n    }\n\n    private suspend fun api(\n        token: String,\n        method: String,\n        path: String,\n        body: JSONObject? = null,\n        extraHeaders: Map<String, String> = emptyMap()\n    ): JSONObject = withContext(Dispatchers.IO) {\n        val builder = Request.Builder()\n            .url(API_BASE + path)\n            .header("Authorization", "Bearer $token")\n            .header("Accept", "application/json")\n        extraHeaders.forEach { (key, value) -> builder.header(key, value) }\n\n        val requestBody = body?.toString()?.toRequestBody("application/json; charset=utf-8".toMediaType())\n        when (method) {\n            "GET" -> builder.get()\n            "POST" -> builder.post(requestBody ?: "{}".toRequestBody("application/json".toMediaType()))\n            "PUT" -> builder.put(requestBody ?: "{}".toRequestBody("application/json".toMediaType()))\n            else -> error("Unsupported Cloudflare method $method")\n        }\n        executeCloudflare(builder.build())\n    }\n\n    private fun executeCloudflare(request: Request): JSONObject {\n        http.newCall(request).execute().use { response ->\n            val raw = response.body?.string().orEmpty()\n            val parsed = runCatching { JSONObject(raw) }.getOrElse { JSONObject().put("raw", raw.take(1200)) }\n            if (!response.isSuccessful || !parsed.optBoolean("success", response.isSuccessful)) {\n                val errors = parsed.optJSONArray("errors")?.toString().orEmpty()\n                val detail = errors.ifBlank { parsed.optString("raw").ifBlank { response.message } }\n                error("Cloudflare HTTP ${response.code}: ${detail.take(900)}")\n            }\n            return parsed\n        }\n    }\n\n    companion object {\n        private const val API_BASE = "https://api.cloudflare.com/client/v4"\n\n        fun safeResourceName(raw: String, fallback: String): String {\n            val clean = raw.lowercase()\n                .replace(Regex("[^a-z0-9-]+"), "-")\n                .replace(Regex("-+"), "-")\n                .trim(\'-\')\n            return clean.ifBlank { fallback }.take(63).trimEnd(\'-\')\n        }\n\n        private fun randomSecret(): String {\n            val bytes = ByteArray(32)\n            SecureRandom().nextBytes(bytes)\n            return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)\n        }\n    }\n}\n'
SCREEN_SOURCE = 'package com.ksp.cryptobot.ui\n\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.rememberScrollState\nimport androidx.compose.foundation.verticalScroll\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.platform.LocalContext\nimport androidx.compose.ui.platform.LocalUriHandler\nimport androidx.compose.ui.text.font.FontWeight\nimport androidx.compose.ui.text.input.PasswordVisualTransformation\nimport androidx.compose.ui.unit.dp\nimport com.ksp.cryptobot.cloudshare.*\nimport kotlinx.coroutines.launch\n\nprivate enum class CloudShareFlow { HOME, CREATE, JOIN, REPAIR, MANAGE }\nprivate enum class CreateStep { WELCOME, TOKEN, ACCOUNT, REVIEW, PROVISIONING, COMPLETE }\nprivate enum class JoinStep { WELCOME, WORKER, INVITE, OPTIONS, COMPLETE }\n\n@Composable\nfun CloudShareScreen() {\n    val context = LocalContext.current\n    val uriHandler = LocalUriHandler.current\n    val store = remember { CloudShareSettingsStore(context) }\n    val engine = remember { CloudShareSyncEngine(context) }\n    val provisioner = remember { CloudShareProvisioner(context) }\n    val scope = rememberCoroutineScope()\n\n    var flow by remember { mutableStateOf(CloudShareFlow.HOME) }\n    var createStep by remember { mutableStateOf(CreateStep.WELCOME) }\n    var joinStep by remember { mutableStateOf(JoinStep.WELCOME) }\n    var busy by remember { mutableStateOf(false) }\n    var status by remember { mutableStateOf("Choose what you want CloudShare to do.") }\n    var checkRows by remember { mutableStateOf<List<CloudShareProvisioningStep>>(emptyList()) }\n\n    var cloudflareToken by remember { mutableStateOf("") }\n    var tokenVerified by remember { mutableStateOf(false) }\n    var accountId by remember { mutableStateOf("") }\n    var accountVerified by remember { mutableStateOf(false) }\n    var workerName by remember { mutableStateOf("cts-cloudshare") }\n    var d1Name by remember { mutableStateOf("cts-cloudshare-db") }\n    var r2Name by remember { mutableStateOf("cts-cloudshare-backups") }\n    var euResidency by remember { mutableStateOf(true) }\n    var showAdvanced by remember { mutableStateOf(false) }\n    var setupResult by remember { mutableStateOf<CloudShareProvisioningResult?>(null) }\n\n    var workerUrl by remember { mutableStateOf(store.apiUrl) }\n    var inviteCode by remember { mutableStateOf("") }\n    var syncMinutes by remember { mutableStateOf(store.syncIntervalMinutes.toString()) }\n    var backfillEnabled by remember { mutableStateOf(store.backfillEnabled) }\n\n    var adminToken by remember { mutableStateOf(store.adminToken()) }\n    var inviteLabel by remember { mutableStateOf("Android invitation") }\n    var adminOutput by remember { mutableStateOf("") }\n\n    fun runAction(block: suspend () -> Unit) {\n        if (busy) return\n        busy = true\n        scope.launch {\n            try {\n                block()\n            } catch (error: Exception) {\n                status = "ERROR: ${error.message ?: error.javaClass.simpleName}"\n            } finally {\n                busy = false\n            }\n        }\n    }\n\n    fun resetCreate() {\n        createStep = CreateStep.WELCOME\n        cloudflareToken = ""\n        tokenVerified = false\n        accountVerified = false\n        checkRows = emptyList()\n        setupResult = null\n        status = "Create a new CloudShare one step at a time."\n    }\n\n    Column(\n        Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(14.dp),\n        verticalArrangement = Arrangement.spacedBy(10.dp)\n    ) {\n        Text("CloudShare Setup Assistant", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold)\n        Text(\n            "CloudShare is optional. Trading and local learning keep working even when Cloudflare is unavailable.",\n            style = MaterialTheme.typography.bodySmall\n        )\n\n        when (flow) {\n            CloudShareFlow.HOME -> {\n                SetupStateCard(store)\n                if (store.apiUrl.isNotBlank()) {\n                    FilledTonalButton(\n                        onClick = { flow = CloudShareFlow.REPAIR },\n                        modifier = Modifier.fillMaxWidth()\n                    ) { Text("Test Current CloudShare") }\n                }\n\n                AssistantChoice(\n                    number = "1",\n                    title = "Set up my own CloudShare",\n                    detail = "The assistant guides you through Cloudflare, verifies every prerequisite, then creates D1, R2 and the Worker automatically."\n                ) {\n                    resetCreate()\n                    flow = CloudShareFlow.CREATE\n                }\n                AssistantChoice(\n                    number = "2",\n                    title = "Join an existing CloudShare",\n                    detail = "Use a Worker URL and invitation code. The assistant tests the connection before registering this phone."\n                ) {\n                    joinStep = JoinStep.WELCOME\n                    status = "Join an existing CloudShare one step at a time."\n                    flow = CloudShareFlow.JOIN\n                }\n                AssistantChoice(\n                    number = "3",\n                    title = "Repair or reconnect",\n                    detail = "Check Worker health, authentication, intelligence sync, backfill and device registration."\n                ) { flow = CloudShareFlow.REPAIR }\n                AssistantChoice(\n                    number = "4",\n                    title = "Manage my CloudShare",\n                    detail = "Create invitations and inspect registered clients after owner setup is complete."\n                ) { flow = CloudShareFlow.MANAGE }\n            }\n\n            CloudShareFlow.CREATE -> {\n                when (createStep) {\n                    CreateStep.WELCOME -> {\n                        WizardProgress("Create your CloudShare", 1, 5)\n                        InstructionCard(\n                            "What the app will do",\n                            listOf(\n                                "Help you create a restricted one-time Cloudflare API token.",\n                                "Verify the token before continuing.",\n                                "Help you find your Cloudflare Account ID and verify all required permissions.",\n                                "Create the D1 database and CloudShare tables.",\n                                "Create the R2 backup bucket.",\n                                "Deploy and bind the CloudShare Worker.",\n                                "Register this phone and run the first sync automatically."\n                            )\n                        )\n                        Text(\n                            "You do not need to choose database, bucket or Worker names unless you open Advanced options later.",\n                            style = MaterialTheme.typography.bodySmall\n                        )\n                        Button(\n                            onClick = { createStep = CreateStep.TOKEN },\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text("Start Setup") }\n                        WizardBack { flow = CloudShareFlow.HOME }\n                    }\n\n                    CreateStep.TOKEN -> {\n                        WizardProgress("Create your CloudShare", 2, 5)\n                        Text("Create the temporary Cloudflare token", fontWeight = FontWeight.Bold)\n                        InstructionCard(\n                            "Do this in Cloudflare",\n                            listOf(\n                                "Tap Open Cloudflare API Tokens below.",\n                                "Choose Create Token → Create Custom Token.",\n                                "Give it a name such as CTS CloudShare Setup.",\n                                "Add account permissions for D1 Write, Workers R2 Storage Write, and Workers Scripts Write.",\n                                "Limit the token to the Cloudflare account you want to use.",\n                                "Create the token and copy it. Cloudflare only shows the secret once.",\n                                "Return here and paste it below."\n                            )\n                        )\n                        OutlinedButton(\n                            onClick = { uriHandler.openUri("https://dash.cloudflare.com/profile/api-tokens") },\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text("Open Cloudflare API Tokens") }\n                        OutlinedTextField(\n                            value = cloudflareToken,\n                            onValueChange = {\n                                cloudflareToken = it\n                                tokenVerified = false\n                            },\n                            label = { Text("Paste temporary API token") },\n                            visualTransformation = PasswordVisualTransformation(),\n                            modifier = Modifier.fillMaxWidth(),\n                            singleLine = true\n                        )\n                        Button(\n                            onClick = {\n                                checkRows = emptyList()\n                                runAction {\n                                    val row = provisioner.verifyProvisioningToken(cloudflareToken)\n                                    checkRows = listOf(row)\n                                    tokenVerified = row.status == "PASS"\n                                    if (tokenVerified) {\n                                        status = "Token verified. Next, copy your Account ID."\n                                        createStep = CreateStep.ACCOUNT\n                                    }\n                                }\n                            },\n                            enabled = !busy && cloudflareToken.isNotBlank(),\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text(if (busy) "Checking Token..." else "Verify Token & Continue") }\n                        ProvisioningSteps(checkRows)\n                        WizardBack { createStep = CreateStep.WELCOME }\n                    }\n\n                    CreateStep.ACCOUNT -> {\n                        WizardProgress("Create your CloudShare", 3, 5)\n                        Text("Copy your Cloudflare Account ID", fontWeight = FontWeight.Bold)\n                        InstructionCard(\n                            "Find the Account ID",\n                            listOf(\n                                "Tap Open Cloudflare Dashboard.",\n                                "Open the account you want Crypto TradeStation to use.",\n                                "Use the menu next to the account name and choose Copy Account ID.",\n                                "Return here and paste the 32-character Account ID.",\n                                "The app will test D1, R2 and Workers access before it lets setup continue."\n                            )\n                        )\n                        OutlinedButton(\n                            onClick = { uriHandler.openUri("https://dash.cloudflare.com/") },\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text("Open Cloudflare Dashboard") }\n                        OutlinedTextField(\n                            value = accountId,\n                            onValueChange = {\n                                accountId = it.trim()\n                                accountVerified = false\n                            },\n                            label = { Text("Cloudflare Account ID") },\n                            supportingText = { Text("Expected: 32 hexadecimal characters") },\n                            modifier = Modifier.fillMaxWidth(),\n                            singleLine = true\n                        )\n                        Button(\n                            onClick = {\n                                checkRows = emptyList()\n                                runAction {\n                                    val rows = provisioner.verifyProvisioningAccess(accountId, cloudflareToken)\n                                    checkRows = rows\n                                    accountVerified = rows.isNotEmpty() && rows.none { it.status == "FAIL" }\n                                    if (accountVerified) {\n                                        status = "Cloudflare account and permissions verified."\n                                        createStep = CreateStep.REVIEW\n                                    } else {\n                                        status = "One or more Cloudflare permissions are missing. Fix the failed item and retry."\n                                    }\n                                }\n                            },\n                            enabled = !busy && tokenVerified && accountId.length == 32,\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text(if (busy) "Checking Permissions..." else "Verify Account & Continue") }\n                        ProvisioningSteps(checkRows)\n                        WizardBack { createStep = CreateStep.TOKEN }\n                    }\n\n                    CreateStep.REVIEW -> {\n                        WizardProgress("Create your CloudShare", 4, 5)\n                        Text("Review setup", fontWeight = FontWeight.Bold)\n                        OutlinedCard(Modifier.fillMaxWidth()) {\n                            Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {\n                                SummaryRow("Cloudflare account", accountId.take(8) + "…")\n                                SummaryRow("Data location", if (euResidency) "EU jurisdiction" else "Cloudflare default")\n                                SummaryRow("Automatic sync", "Every ${syncMinutes.toIntOrNull() ?: 5} minutes")\n                                SummaryRow("Historical backfill", if (backfillEnabled) "Enabled" else "Disabled")\n                                SummaryRow("Worker", workerName)\n                                SummaryRow("D1", d1Name)\n                                SummaryRow("R2", r2Name)\n                            }\n                        }\n                        Row(verticalAlignment = androidx.compose.ui.Alignment.CenterVertically) {\n                            Switch(checked = euResidency, onCheckedChange = { euResidency = it })\n                            Spacer(Modifier.width(8.dp))\n                            Text("Keep CloudShare D1/R2 in EU jurisdiction")\n                        }\n                        OutlinedTextField(\n                            value = syncMinutes,\n                            onValueChange = { syncMinutes = it.filter(Char::isDigit) },\n                            label = { Text("Automatic sync interval (minutes)") },\n                            modifier = Modifier.fillMaxWidth(),\n                            singleLine = true\n                        )\n                        Row(verticalAlignment = androidx.compose.ui.Alignment.CenterVertically) {\n                            Switch(checked = backfillEnabled, onCheckedChange = { backfillEnabled = it })\n                            Spacer(Modifier.width(8.dp))\n                            Text("Upload existing learning/history during backfill")\n                        }\n                        TextButton(onClick = { showAdvanced = !showAdvanced }) {\n                            Text(if (showAdvanced) "Hide Advanced Resource Names" else "Advanced Resource Names")\n                        }\n                        if (showAdvanced) {\n                            Text("You normally do not need to change these.", style = MaterialTheme.typography.bodySmall)\n                            OutlinedTextField(workerName, { workerName = it }, label = { Text("Worker name") }, modifier = Modifier.fillMaxWidth(), singleLine = true)\n                            OutlinedTextField(d1Name, { d1Name = it }, label = { Text("D1 database name") }, modifier = Modifier.fillMaxWidth(), singleLine = true)\n                            OutlinedTextField(r2Name, { r2Name = it }, label = { Text("R2 bucket name") }, modifier = Modifier.fillMaxWidth(), singleLine = true)\n                        }\n                        Button(\n                            onClick = {\n                                checkRows = emptyList()\n                                setupResult = null\n                                createStep = CreateStep.PROVISIONING\n                                runAction {\n                                    val result = provisioner.provision(\n                                        accountId = accountId,\n                                        apiToken = cloudflareToken,\n                                        workerName = workerName,\n                                        d1Name = d1Name,\n                                        r2BucketName = r2Name,\n                                        euResidency = euResidency,\n                                        backfillEnabled = backfillEnabled,\n                                        syncIntervalMinutes = syncMinutes.toIntOrNull() ?: 5,\n                                        onProgress = { row -> checkRows = checkRows + row }\n                                    )\n                                    setupResult = result\n                                    cloudflareToken = ""\n                                    tokenVerified = false\n                                    if (result.success) {\n                                        workerUrl = result.workerUrl\n                                        status = "CloudShare was created and verified successfully."\n                                        createStep = CreateStep.COMPLETE\n                                    } else {\n                                        status = "Setup stopped at the failed step. Correct it and retry."\n                                    }\n                                }\n                            },\n                            enabled = !busy && accountVerified,\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text("Create My CloudShare") }\n                        WizardBack { createStep = CreateStep.ACCOUNT }\n                    }\n\n                    CreateStep.PROVISIONING -> {\n                        WizardProgress("Create your CloudShare", 5, 5)\n                        Text("Automatic setup in progress", fontWeight = FontWeight.Bold)\n                        Text(\n                            "You can stay on this screen. Crypto TradeStation is creating and testing each CloudShare component in order.",\n                            style = MaterialTheme.typography.bodySmall\n                        )\n                        if (busy) LinearProgressIndicator(Modifier.fillMaxWidth())\n                        ProvisioningSteps(checkRows)\n                        val failed = setupResult?.success == false\n                        if (failed) {\n                            Button(\n                                onClick = { createStep = CreateStep.REVIEW },\n                                modifier = Modifier.fillMaxWidth()\n                            ) { Text("Review & Retry") }\n                        }\n                    }\n\n                    CreateStep.COMPLETE -> {\n                        WizardProgress("Create your CloudShare", 5, 5)\n                        Text("CloudShare is ready", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)\n                        SetupStateCard(store)\n                        setupResult?.let { result ->\n                            OutlinedCard(Modifier.fillMaxWidth()) {\n                                Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {\n                                    Text("Created successfully", fontWeight = FontWeight.Bold)\n                                    Text("Worker: ${result.workerUrl}", style = MaterialTheme.typography.bodySmall)\n                                    Text("D1 database: ${result.d1DatabaseId.take(10)}…", style = MaterialTheme.typography.bodySmall)\n                                    Text("R2 bucket: ${result.r2BucketName}", style = MaterialTheme.typography.bodySmall)\n                                    Text("This phone: Registered", style = MaterialTheme.typography.bodySmall)\n                                }\n                            }\n                        }\n                        OutlinedButton(\n                            onClick = {\n                                checkRows = emptyList()\n                                runAction {\n                                    checkRows = provisioner.verifyExisting(store.apiUrl)\n                                    status = if (checkRows.any { it.status == "FAIL" }) "Final test found a problem." else "Final CloudShare test passed."\n                                }\n                            },\n                            enabled = !busy,\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text("Run Final CloudShare Test") }\n                        ProvisioningSteps(checkRows)\n                        Button(\n                            onClick = { flow = CloudShareFlow.HOME },\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text("Finish") }\n                    }\n                }\n            }\n\n            CloudShareFlow.JOIN -> {\n                when (joinStep) {\n                    JoinStep.WELCOME -> {\n                        WizardProgress("Join an existing CloudShare", 1, 3)\n                        InstructionCard(\n                            "You need two things",\n                            listOf(\n                                "The CloudShare Worker HTTPS URL from the owner.",\n                                "A valid invitation code created by that CloudShare owner."\n                            )\n                        )\n                        Button(onClick = { joinStep = JoinStep.WORKER }, modifier = Modifier.fillMaxWidth()) { Text("Start") }\n                        WizardBack { flow = CloudShareFlow.HOME }\n                    }\n                    JoinStep.WORKER -> {\n                        WizardProgress("Join an existing CloudShare", 2, 3)\n                        Text("Test the Worker first", fontWeight = FontWeight.Bold)\n                        OutlinedTextField(\n                            workerUrl, { workerUrl = it.trim() },\n                            label = { Text("CloudShare Worker HTTPS URL") },\n                            modifier = Modifier.fillMaxWidth(), singleLine = true\n                        )\n                        Button(\n                            onClick = {\n                                runAction {\n                                    store.apiUrl = workerUrl\n                                    val health = engine.health()\n                                    status = "Worker health passed: $health"\n                                    joinStep = JoinStep.INVITE\n                                }\n                            },\n                            enabled = !busy && workerUrl.startsWith("https://"),\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text("Test Worker & Continue") }\n                        WizardBack { joinStep = JoinStep.WELCOME }\n                    }\n                    JoinStep.INVITE -> {\n                        WizardProgress("Join an existing CloudShare", 3, 3)\n                        Text("Register this phone", fontWeight = FontWeight.Bold)\n                        OutlinedTextField(\n                            inviteCode, { inviteCode = it },\n                            label = { Text("Invitation code") },\n                            visualTransformation = PasswordVisualTransformation(),\n                            modifier = Modifier.fillMaxWidth(), singleLine = true\n                        )\n                        Button(\n                            onClick = {\n                                runAction {\n                                    store.apiUrl = workerUrl\n                                    val credentials = engine.register(inviteCode)\n                                    inviteCode = ""\n                                    val client = CloudShareClient(store.apiUrl, credentials = credentials)\n                                    client.clientStatus()\n                                    client.intelligenceStatus()\n                                    status = "Device registration passed. Choose sync options."\n                                    joinStep = JoinStep.OPTIONS\n                                }\n                            },\n                            enabled = !busy && inviteCode.isNotBlank(),\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text("Register & Verify") }\n                        WizardBack { joinStep = JoinStep.WORKER }\n                    }\n                    JoinStep.OPTIONS -> {\n                        WizardProgress("Join an existing CloudShare", 3, 3)\n                        Text("Finish synchronization setup", fontWeight = FontWeight.Bold)\n                        OutlinedTextField(\n                            syncMinutes,\n                            { syncMinutes = it.filter(Char::isDigit) },\n                            label = { Text("Automatic sync interval (minutes)") },\n                            modifier = Modifier.fillMaxWidth(), singleLine = true\n                        )\n                        Row(verticalAlignment = androidx.compose.ui.Alignment.CenterVertically) {\n                            Switch(checked = backfillEnabled, onCheckedChange = { backfillEnabled = it })\n                            Spacer(Modifier.width(8.dp))\n                            Text("Backfill existing learning/history")\n                        }\n                        Button(\n                            onClick = {\n                                runAction {\n                                    store.syncIntervalMinutes = syncMinutes.toIntOrNull() ?: 5\n                                    store.backfillEnabled = backfillEnabled\n                                    store.enabled = true\n                                    val result = engine.syncIfDue(force = true)\n                                    require(result.error.isBlank()) { result.error }\n                                    status = "CloudShare joined. uploaded=${result.uploaded}, downloaded=${result.downloaded}, backfill=${result.backfilled}"\n                                    joinStep = JoinStep.COMPLETE\n                                }\n                            },\n                            enabled = !busy,\n                            modifier = Modifier.fillMaxWidth()\n                        ) { Text("Run Initial Sync") }\n                    }\n                    JoinStep.COMPLETE -> {\n                        Text("CloudShare joined successfully", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)\n                        SetupStateCard(store)\n                        Button(onClick = { flow = CloudShareFlow.HOME }, modifier = Modifier.fillMaxWidth()) { Text("Finish") }\n                    }\n                }\n            }\n\n            CloudShareFlow.REPAIR -> {\n                Text("Repair & Test CloudShare", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)\n                SetupStateCard(store)\n                Button(\n                    onClick = {\n                        checkRows = emptyList()\n                        runAction {\n                            checkRows = provisioner.verifyExisting(store.apiUrl)\n                            status = if (checkRows.any { it.status == "FAIL" }) "CloudShare needs attention." else "CloudShare verification passed."\n                        }\n                    },\n                    enabled = !busy && store.apiUrl.startsWith("https://"),\n                    modifier = Modifier.fillMaxWidth()\n                ) { Text("Run Full CloudShare Test") }\n                OutlinedButton(\n                    onClick = {\n                        runAction {\n                            val result = engine.syncIfDue(force = true)\n                            status = "Sync: uploaded=${result.uploaded}, downloaded=${result.downloaded}, backfill=${result.backfilled}" +\n                                if (result.error.isBlank()) "" else ", error=${result.error}"\n                        }\n                    },\n                    enabled = !busy && store.enabled,\n                    modifier = Modifier.fillMaxWidth()\n                ) { Text("Force Sync Now") }\n                OutlinedButton(\n                    onClick = {\n                        runAction { status = "Bootstrap upload: ${engine.createAndUploadBootstrap()}" }\n                    },\n                    enabled = !busy && store.credentials() != null,\n                    modifier = Modifier.fillMaxWidth()\n                ) { Text("Upload Full Bootstrap") }\n                ProvisioningSteps(checkRows)\n                WizardBack { flow = CloudShareFlow.HOME }\n            }\n\n            CloudShareFlow.MANAGE -> {\n                Text("Manage CloudShare", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)\n                Text("Owner controls are only needed after CloudShare has been created.", style = MaterialTheme.typography.bodySmall)\n                OutlinedTextField(\n                    adminToken, { adminToken = it },\n                    label = { Text("CloudShare owner/admin token") },\n                    visualTransformation = PasswordVisualTransformation(),\n                    modifier = Modifier.fillMaxWidth(), singleLine = true\n                )\n                Button(\n                    onClick = {\n                        store.saveAdminToken(adminToken)\n                        runAction {\n                            adminOutput = engine.adminPing().toString()\n                            status = "Owner authentication passed."\n                        }\n                    },\n                    enabled = !busy && adminToken.isNotBlank() && store.apiUrl.isNotBlank(),\n                    modifier = Modifier.fillMaxWidth()\n                ) { Text("Verify Owner") }\n                OutlinedTextField(\n                    inviteLabel, { inviteLabel = it },\n                    label = { Text("New invitation label") },\n                    modifier = Modifier.fillMaxWidth(), singleLine = true\n                )\n                OutlinedButton(\n                    onClick = {\n                        store.saveAdminToken(adminToken)\n                        runAction {\n                            adminOutput = engine.adminCreateInvite(inviteLabel).toString()\n                            status = "Invitation created. Copy invite_code from the result."\n                        }\n                    },\n                    enabled = !busy && adminToken.isNotBlank(),\n                    modifier = Modifier.fillMaxWidth()\n                ) { Text("Create Invitation") }\n                Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                    OutlinedButton(\n                        onClick = {\n                            store.saveAdminToken(adminToken)\n                            runAction { adminOutput = engine.adminInvites().toString() }\n                        },\n                        enabled = !busy && adminToken.isNotBlank(),\n                        modifier = Modifier.weight(1f)\n                    ) { Text("Invites") }\n                    OutlinedButton(\n                        onClick = {\n                            store.saveAdminToken(adminToken)\n                            runAction { adminOutput = engine.adminClients().toString() }\n                        },\n                        enabled = !busy && adminToken.isNotBlank(),\n                        modifier = Modifier.weight(1f)\n                    ) { Text("Clients") }\n                }\n                if (adminOutput.isNotBlank()) {\n                    OutlinedCard(Modifier.fillMaxWidth()) {\n                        Text(adminOutput, Modifier.padding(10.dp), style = MaterialTheme.typography.bodySmall)\n                    }\n                }\n                WizardBack { flow = CloudShareFlow.HOME }\n            }\n        }\n\n        HorizontalDivider()\n        Text("Assistant Status", fontWeight = FontWeight.Bold)\n        Text(status, style = MaterialTheme.typography.bodySmall)\n        if (busy && createStep != CreateStep.PROVISIONING) {\n            LinearProgressIndicator(Modifier.fillMaxWidth())\n        }\n    }\n}\n\n@Composable\nprivate fun WizardProgress(title: String, step: Int, total: Int) {\n    Column(verticalArrangement = Arrangement.spacedBy(5.dp)) {\n        Text(title, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)\n        Text("Step $step of $total", style = MaterialTheme.typography.labelMedium)\n        LinearProgressIndicator(\n            progress = step.toFloat() / total.toFloat(),\n            modifier = Modifier.fillMaxWidth()\n        )\n    }\n}\n\n@Composable\nprivate fun InstructionCard(title: String, lines: List<String>) {\n    OutlinedCard(Modifier.fillMaxWidth()) {\n        Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(7.dp)) {\n            Text(title, fontWeight = FontWeight.Bold)\n            lines.forEachIndexed { index, line ->\n                Text("${index + 1}. $line", style = MaterialTheme.typography.bodySmall)\n            }\n        }\n    }\n}\n\n@Composable\nprivate fun SetupStateCard(store: CloudShareSettingsStore) {\n    OutlinedCard(Modifier.fillMaxWidth()) {\n        Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {\n            Text("Current CloudShare", fontWeight = FontWeight.Bold)\n            Text("Worker: ${store.apiUrl.ifBlank { "Not configured" }}", style = MaterialTheme.typography.bodySmall)\n            Text("This phone: ${if (store.credentials() != null) "Registered" else "Not registered"}", style = MaterialTheme.typography.bodySmall)\n            Text("Automatic sync: ${if (store.enabled) "Enabled" else "Disabled"}", style = MaterialTheme.typography.bodySmall)\n            Text("Interval: ${store.syncIntervalMinutes} minutes", style = MaterialTheme.typography.bodySmall)\n        }\n    }\n}\n\n@Composable\nprivate fun AssistantChoice(number: String, title: String, detail: String, onClick: () -> Unit) {\n    ElevatedCard(Modifier.fillMaxWidth()) {\n        Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {\n            Text("$number. $title", fontWeight = FontWeight.Bold)\n            Text(detail, style = MaterialTheme.typography.bodySmall)\n            Button(onClick = onClick, modifier = Modifier.fillMaxWidth()) { Text("Continue") }\n        }\n    }\n}\n\n@Composable\nprivate fun SummaryRow(name: String, value: String) {\n    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {\n        Text(name, style = MaterialTheme.typography.bodySmall)\n        Text(value, style = MaterialTheme.typography.bodySmall, fontWeight = FontWeight.SemiBold)\n    }\n}\n\n@Composable\nprivate fun WizardBack(onClick: () -> Unit) {\n    TextButton(onClick = onClick, modifier = Modifier.fillMaxWidth()) { Text("Back") }\n}\n\n@Composable\nprivate fun ProvisioningSteps(rows: List<CloudShareProvisioningStep>) {\n    if (rows.isEmpty()) return\n    OutlinedCard(Modifier.fillMaxWidth()) {\n        Column(Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {\n            Text("Verification / setup progress", fontWeight = FontWeight.Bold)\n            rows.takeLast(40).forEach { row ->\n                val color = when (row.status) {\n                    "PASS" -> MaterialTheme.colorScheme.secondary\n                    "FAIL" -> MaterialTheme.colorScheme.error\n                    "WARN" -> MaterialTheme.colorScheme.tertiary\n                    else -> MaterialTheme.colorScheme.primary\n                }\n                Text(\n                    "${row.status} • ${row.name}",\n                    color = color,\n                    fontWeight = FontWeight.SemiBold,\n                    style = MaterialTheme.typography.bodySmall\n                )\n                Text(row.detail, style = MaterialTheme.typography.labelSmall)\n            }\n        }\n    }\n}\n'

def fail(message: str) -> None:
    raise SystemExit(f"[CTS CloudShare guided assistant] {message}")

def main() -> None:
    if len(sys.argv) != 2:
        fail("usage: apply_cloudshare_guided_assistant.py <repo-root>")
    repo = Path(sys.argv[1]).resolve()
    root = repo / "app/src/main/java/com/ksp/cryptobot"
    provisioner = root / "cloudshare/CloudShareProvisioner.kt"
    screen = root / "ui/CloudShareScreen.kt"
    if not provisioner.exists() or not screen.exists():
        fail("CloudShare v4.0.6 setup baseline is missing; run apply_cloudshare_setup_wizard.py first.")

    provisioner.write_text(PROVISIONER_SOURCE.rstrip() + "\n", encoding="utf-8")
    screen.write_text(SCREEN_SOURCE.rstrip() + "\n", encoding="utf-8")

    checks = {
        "sequential create flow": "CreateStep.WELCOME" in SCREEN_SOURCE and "CreateStep.TOKEN" in SCREEN_SOURCE and "CreateStep.ACCOUNT" in SCREEN_SOURCE and "CreateStep.REVIEW" in SCREEN_SOURCE and "CreateStep.PROVISIONING" in SCREEN_SOURCE and "CreateStep.COMPLETE" in SCREEN_SOURCE,
        "no setup tab form": "ScrollableTabRow" not in SCREEN_SOURCE and "CloudShareWizardPanel" not in SCREEN_SOURCE,
        "visible step progress": "Step $step of $total" in SCREEN_SOURCE and "WizardProgress" in SCREEN_SOURCE,
        "opens Cloudflare token page": "https://dash.cloudflare.com/profile/api-tokens" in SCREEN_SOURCE,
        "opens Cloudflare dashboard": "https://dash.cloudflare.com/" in SCREEN_SOURCE,
        "token verified before account": "verifyProvisioningToken" in SCREEN_SOURCE and "verifyProvisioningToken" in PROVISIONER_SOURCE,
        "permissions verified before provisioning": "verifyProvisioningAccess" in SCREEN_SOURCE and "verifyProvisioningAccess" in PROVISIONER_SOURCE,
        "D1 permission check": "D1 Write access" in PROVISIONER_SOURCE,
        "R2 permission check": "R2 Storage Write access" in PROVISIONER_SOURCE,
        "Workers permission check": "Workers Scripts Write access" in PROVISIONER_SOURCE,
        "advanced names hidden by default": "showAdvanced" in SCREEN_SOURCE and "You normally do not need to change these" in SCREEN_SOURCE,
        "automatic provision after review": "Create My CloudShare" in SCREEN_SOURCE and "provisioner.provision(" in SCREEN_SOURCE,
        "live provisioning progress": "onProgress = { row -> checkRows = checkRows + row }" in SCREEN_SOURCE,
        "final verification": "Run Final CloudShare Test" in SCREEN_SOURCE,
        "sequential join flow": "JoinStep.WORKER" in SCREEN_SOURCE and "JoinStep.INVITE" in SCREEN_SOURCE and "JoinStep.OPTIONS" in SCREEN_SOURCE,
        "Cloudflare token not persisted": "saveCloudflare" not in SCREEN_SOURCE and "saveCloudflare" not in PROVISIONER_SOURCE,
        "token cleared after provisioning": 'cloudflareToken = ""' in SCREEN_SOURCE,
    }
    for name, ok in checks.items():
        print(("PASS" if ok else "FAIL") + " | " + name)
    failed = [name for name, ok in checks.items() if not ok]
    if failed:
        fail("validation failed: " + ", ".join(failed))
    print("[CTS CloudShare guided assistant] Applied successfully.")

if __name__ == "__main__":
    main()
